"""Deterministic, cited reporting; no uncited numerical claims are generated by an LLM."""

import html
import re
from datetime import date
from typing import Any
from urllib.parse import urlparse


def escape(value: object) -> str:
    text = html.escape(str(value), quote=False).replace("\n", " ")
    for char in ("\\", "[", "]", "*", "_", "`", "|", "#"):
        text = text.replace(char, "\\" + char)
    return text


def matches_project(project: str, record_project: str, deposit: str) -> bool:
    text = (record_project + " " + deposit).casefold()
    if project.casefold() in {"pilbara", "pilgangoora", "皮尔巴拉"}:
        return "pilbara" in text or "pilgangoora" in text
    return project.casefold() in text


def quantity(record: dict[str, Any], name: str) -> str:
    return f"{record[name]['value']:g} {record[name]['unit']}"


def render_report(result: dict[str, Any]) -> str:
    plan = result["plan"]
    demo = result["mode"] == "demo"
    references: list[str] = []
    risks: list[str] = []

    def cite(urls: list[str]) -> str:
        labels = []
        for url in urls:
            if url not in references:
                references.append(url)
            labels.append(f"[S{references.index(url) + 1}]")
        return " ".join(labels)

    lines = [
        f"# {escape(plan['project'])} 矿权日报",
        "",
        f"报告日期：{plan['as_of']}（Asia/Shanghai）｜新闻窗口：近 {plan['days']} 个自然日",
        "",
    ]
    if demo:
        lines += ["> **离线演示：新闻、资源和价格均为合成样例，不是真实行情或公司披露。**", ""]
    lines += ["## 新闻摘要", ""]
    if not result["articles"]:
        lines.append("未获得符合时间范围的项目新闻。不能据此认定该项目没有发生变化。")
    for entry in result["articles"]:
        item, article = entry["item"], entry["article"]
        body = article["data"].get("text") or item["summary"]
        label = "原文摘录" if article["data"].get("text") else "RSS 摘要（正文未获取）"
        sentences = re.split(r"(?<=[。.!?])\s+", body)
        summary = " ".join(sentences[:2])[:500]
        lines += [
            f"- **{escape(item['title'])}**（{escape(item['published_at'][:10])}）"
            f"{cite([item['url']])}",
            f"  {label}：{escape(summary)}",
        ]
        risks.extend(article["warnings"])
    lines += [
        "",
        "## 资源量与报告口径",
        "",
        "资源量（Resources）不等于可采储量（Reserves）；以下数据按报告日期披露。",
        "",
    ]
    records = result["resources"]["data"].get("records", [])
    valid_records = []
    for record in records:
        if not matches_project(plan["project"], record["project"], record["deposit"]):
            risks.append("PDF 项目与日报项目不一致，已隐藏资源数值。")
            continue
        if record["effective_date"] > plan["as_of"]:
            risks.append("资源数据生效日在日报日期之后，已隐藏数值。")
            continue
        valid_records.append(record)
    if valid_records:
        lines += [
            "| 矿区 | 分类 | 矿石量 | 品位 | 披露金属／氧化物量 | 日期／标准 |",
            "|---|---|---:|---:|---:|---|",
        ]
        for r in valid_records:
            lines.append(
                f"| {escape(r['deposit'])} | {r['category']} | {quantity(r, 'ore')} | "
                f"{quantity(r, 'grade')} {r['commodity']} | {quantity(r, 'contained_metal')} | "
                f"{r['effective_date']} / {r['standard']} |"
            )
        lines.append("")
        for r in valid_records:
            lines.append(
                f"- {escape(r['deposit'])} {r['category']}：cut-off `{escape(r['cutoff'])}`；"
                f"储量包含口径 `{r['basis']}`；PDF 第 {r['category_evidence']['page']} 页。"
                f"{cite(result['resources']['sources'])}"
            )
            age = (date.fromisoformat(plan["as_of"]) - date.fromisoformat(r["effective_date"])).days
            if age > 365:
                risks.append(f"资源报告距日报日期已超过一年（{age} 天），不代表今日新增资源。")
        if any(r["standard"] == "JORC" for r in valid_records):
            risks.append("该资源数据按 JORC 披露，不能称为 NI 43-101 报告。")
    else:
        lines.append("未获得通过证据校验且匹配项目的资源数据；请补充技术报告后复核。")
    lines += ["", "## 价格与走势", ""]
    quote = result["price"]["data"].get("points", [])
    trend = result["trend"]["data"]
    points = trend.get("points", [])
    if quote:
        p = quote[-1]
        lines.append(
            f"指定日期 {p['date']}：**{p['price']:g} {p['currency']}/{p['unit']}**；"
            f"{escape(p['contract'])}。{cite(result['price']['sources'])}"
        )
    else:
        lines.append("指定日期没有可核验报价；未使用上一交易日数值冒充当日报价。")
    if points:
        lines += ["", "| 观测日期 | 价格 |", "|---|---:|"]
        for p in points:
            lines.append(f"| {p['date']} | {p['price']:g} {p['currency']}/{p['unit']} |")
        change = trend.get("change_pct")
        if change is not None:
            lines.append(
                f"\n窗口内首末观测值变化：**{change:+.2f}%**"
                f"（{points[0]['date']} 至 {points[-1]['date']}，共 {len(points)} 个观测值）。"
                f"{cite(result['trend']['sources'])}"
            )
    else:
        lines.append("价格走势数据不可用。")
    if plan["commodity"] == "lithium":
        risks.append("氢氧化锂合约、锂辉石精矿报价及矿石中的 Li2O 含量口径不同，不可直接替代。")
    for section in ("news", "resources", "price", "trend"):
        if result[section]["status"] != "ok":
            risks.append(f"{section} 数据状态：{result[section]['status']}。")
        risks.extend(result[section]["warnings"])
    lines += ["", "## 风险与待核验事项", ""]
    lines += [f"- {escape(w)}" for w in dict.fromkeys(risks) if not w.startswith("SYNTHETIC_DEMO")]
    lines += ["- 新闻采用带来源的摘录；未从新闻或资源表推断采矿权法律状态。", "", "## 引用来源", ""]
    for i, url in enumerate(references, 1):
        if urlparse(url).scheme == "https":
            safe = url.replace("<", "%3C").replace(">", "%3E").replace("\n", "")
            lines.append(f"- [S{i}] [来源链接](<{safe}>)")
        elif urlparse(url).scheme == "demo":
            lines.append(
                f"- [S{i}] 演示引用 `{escape(url)}`，"
                "对应仓库 `src/mining_daily/fixtures/` 中的合成数据。"
            )
        else:
            lines.append(f"- [S{i}] 来源 URL 使用不支持的协议，未生成可点击链接。")
    lines += [
        "",
        "## 执行记录",
        "",
        f"通过 MCP 协议调用 {len(result['trace'])} 次工具；发现 3 个独立 Server。"
        "完整工具响应和耗时见同名 JSON。",
        "",
    ]
    return "\n".join(lines)
